let date = nowRfc3339();
seq.put(http.requestHeaders, 'X-Login', params.xLogin);
seq.put(http.requestHeaders, 'X-Trans-Key', params.xTransKey);
seq.put(http.requestHeaders, 'X-Version', '2.1');
seq.put(http.requestHeaders, 'User-Agent', 'MoR-Platform');
seq.put(http.requestHeaders, 'X-Date', date);
seq.put(http.requestHeaders, 'X-Idempotency-Key', params.idempotencyKey);
seq.put(http.requestHeaders, 'Authorization',
  'V2-HMAC-SHA256, Signature: ' + hmacSha256Hex(params.secretKey, params.xLogin + date + sealJsonBody(http)));

let s = nowRfc3339();
let y = long(string.substring(s, 0, 4));
let m = long(string.substring(s, 5, 7));
let d = long(string.substring(s, 8, 10));
let hh = long(string.substring(s, 11, 13));
let mi = long(string.substring(s, 14, 16));
let ss = long(string.substring(s, 17, 19));
let ms = long(string.substring(s, 20, 23));
let yy = m <= 2 ? y - 1 : y;
let era = yy / 400;
let yoe = yy - era * 400;
let mp = m > 2 ? m - 3 : m + 9;
let doy = (153 * mp + 2) / 5 + d - 1;
let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
let days = era * 146097 + doe - 719468;
json.set(http.requestBody, 'requestTime', ((days * 24 + hh) * 60 + mi) * 60000 + ss * 1000 + ms);
http.requestHeaders.sign = rsaSha256Sign(params.privateKey, sealJsonBody(http));

if (http.responseStatus == 200 && http.responseBody != nil && http.responseBody.head.applyStatus == 'SUCCESS') {
  requireRsaSha256Signature(params.publicKey, http.responseRaw, http.responseHeaders.sign);
}

if (http.responseBody != nil && http.responseBody.transactions != nil) {
  for item in http.responseBody.transactions {
    if (item.stepType == 'REFUND' && item.refundNo == params.refundId) {
      http.responseBody.refundRecord = item;
    }
  }
}
